from collections import deque
class SchemaError(Exception): pass
class Mapping(dict):
    def __init__(self, exc):
        super().__init__(leaf=7)
        self.exc=exc
    @property
    def __dict__(self):
        raise self.exc('attribute lookup')

def scan(patched, exc):
    q=deque([('root', Mapping(exc)), ('later', [9])]); visited=set(); hits=[]
    def add(path, value):
        if isinstance(value,int): hits.append((path,value))
        if id(value) not in visited:
            visited.add(id(value)); q.append((path,value))
    def attrs(path,obj):
        if hasattr(obj,'__dict__'):
            for attr,value in obj.__dict__.items(): add(f'{path}.{attr}',value)
    try:
        while q:
            path,obj=q.popleft()
            if patched:
                try: attrs(path,obj)
                except SchemaError: pass
            else: attrs(path,obj)
            if isinstance(obj,dict):
                try:
                    for k,v in obj.items(): add(f'{path}[{k!r}]',v)
                except: pass
            if isinstance(obj,(list,tuple,set)):
                for i,v in enumerate(obj): add(f'{path}[{i}]',v)
    except Exception as e: return type(e).__name__,hits
    return 'finished',hits
old=scan(False,SchemaError); new=scan(True,SchemaError); other=scan(True,RuntimeError)
assert old==('SchemaError',[]) and new==('finished',[("root['leaf']",7),('later[0]',9)]) and other==('RuntimeError',[])
print(old,new,other,sep='\n')
